const rows = $('Aplicar acceso').all().map((item) => item.json);
const grant = rows.find((row) => ['alta', 'actualizado'].includes(String(row.resultado)) && row.telegram_user_id);
if (!grant) return [{ json: { avisar: false } }];
const name = String(grant.name || '').trim();
const safe = name.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const text = safe && safe !== 'Usuario Telegram'
  ? `Listo, ${safe}. Ya puedes usar el asistente. Escribe de nuevo lo que necesitas.`
  : 'Listo. Ya puedes usar el asistente. Escribe de nuevo lo que necesitas.';
return [{ json: { avisar: true, chatId: String(grant.telegram_user_id), text } }];

const rows = $('Aplicar acceso').all().map((item) => item.json);
let sent = false;
try {
  const telegram = $('Avisar persona');
  sent = Boolean(telegram.isExecuted) && !telegram.first()?.json?.error;
} catch (error) {
  sent = false;
}
const source = rows.length ? rows : [{ resultado: 'sin_cambios' }];
return source.map((row) => ({
  json: {
    ...row,
    aviso: ['alta', 'actualizado'].includes(String(row.resultado))
      ? (sent ? 'enviado' : 'no_enviado')
      : 'no_aplica',
  },
}));
